extern char *environ[];extern int os9forkc(), chainc(), errno;int execve_m(prog, argv, envp, mem)char *prog;char *argv[];char *envp[];int mem;{   int status;      switch(laccess(argv[0], prog))   {      default: return(errno);      case 0:     /* user state module */         return os9exec(chainc, prog, argv, envp, mem<<10, 0, 3);      case 1:     /* system state module - chainc() buggy, use os9forkc(): */         if ( (os9exec(os9forkc, prog, argv, envp, mem<<10, 0, 3)) > 0)         {            (void) wait(&status);            exit(status);         }         return(errno);   }}int execve(prog, argv, envp)char *prog;char *argv[];char *envp[];{   return(execve_m(prog, argv, envp, 0));}